"OriginalThreePaymentSample": func(t *testing.T) {
	example(t, "testdata/original/sample-request.json", []int64{625000, 580050, 120075}, []int64{3674875, 170075, 1405050})
},

func example(t *testing.T, file string, cents, balances []int64) {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(suite.root, file))
	if err != nil {
		t.Fatal(err)
	}
	var b batch
	if err := json.Unmarshal(data, &b); err != nil {
		t.Fatal(err)
	}
	expect(t, call(t, 0, string(data)), 201, "")
	var rows []record
	for i, p := range b.Payments {
		id := 2
		if p.Payee == nair {
			id = 3
		}
		rows = append(rows, record{1, id, cents[i], p.Description})
	}
	checkState(t, balances, rows)
}

func call(t *testing.T, index int, body string) response {
	t.Helper()
	res, err := request(t.Context(), "http://"+suite.apis[index].addr, http.MethodPost, "/payments/bulk", "application/json", body)
	if err != nil {
		t.Fatal(err)
	}
	return res
}

func checkState(t *testing.T, balances []int64, payments []record) {
	t.Helper()
	want := state{Balances: balances, Payments: payments}
	if payments == nil {
		want.Payments = []record{}
	}
	if got := snapshot(t); !reflect.DeepEqual(got, want) {
		t.Fatalf("state %+v; want %+v", got, want)
	}
}

func expect(t *testing.T, got response, status int, code string) {
	t.Helper()
	if got.Status != status || got.Code != code || (status == 201 && got.Body != "") {
		t.Fatalf("response %+v; want %d/%s", got, status, code)
	}
}

func request(ctx context.Context, base, method, path, media, body string) (response, error) {
	req, err := http.NewRequestWithContext(ctx, method, base+path, strings.NewReader(body))
	if err != nil {
		return response{}, err
	}
	if media != "" {
		req.Header.Set("Content-Type", media)
	}
	res, err := suite.client.Do(req)
	if err != nil {
		return response{}, err
	}
	defer func() { _ = res.Body.Close() }()
	data, err := io.ReadAll(io.LimitReader(res.Body, 2<<20))
	if err != nil {
		return response{}, err
	}
	var failure struct {
		Error struct {
			Code string `json:"code"`
		}
	}
	if res.StatusCode != 201 && res.StatusCode != 404 && res.StatusCode != 405 {
		if err := json.Unmarshal(data, &failure); err != nil {
			return response{}, err
		}
	}
	return response{res.StatusCode, string(data), failure.Error.Code}, nil
}

func snapshot(t *testing.T) state {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
	defer cancel()
	s := state{Balances: []int64{}, Payments: []record{}}
	rows, err := suite.db.Query(ctx, "SELECT balance_cents FROM firms ORDER BY id")
	if err != nil {
		t.Fatal(err)
	}
	for rows.Next() {
		var cents int64
		if err := rows.Scan(&cents); err != nil {
			rows.Close()
			t.Fatal(err)
		}
		s.Balances = append(s.Balances, cents)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	rows, err = suite.db.Query(ctx, "SELECT payer_firm_id,payee_firm_id,amount_cents,description FROM payments ORDER BY id")
	if err != nil {
		t.Fatal(err)
	}
	defer rows.Close()
	for rows.Next() {
		var r record
		if err := rows.Scan(&r.Payer, &r.Payee, &r.Cents, &r.Description); err != nil {
			t.Fatal(err)
		}
		s.Payments = append(s.Payments, r)
	}
	if err := rows.Err(); err != nil {
		t.Fatal(err)
	}
	return s
}

