"MaximumBatchAccepted": func(t *testing.T) {
	b := transfer("0.01")
	b.Payments = nil
	want := []record{}
	for range 1000 {
		b.Payments = append(b.Payments, entry{"0.01", lopez, "one cent"})
		want = append(want, record{1, 2, 1, "one cent"})
	}
	accepted(t, b)
	checkState(t, []int64{4999000, 51000, 200000}, want)
},

