func missingFields(t *testing.T) {
	t.Helper()
	source := encode(t, transfer("1"))
	for _, payment := range []bool{false, true} {
		fields := []string{"payer_firm_uuid", "payments"}
		if payment {
			fields = []string{"amount", "payee_firm_uuid", "description"}
		}
		for _, field := range fields {
			for _, null := range []bool{false, true} {
				var root map[string]any
				if err := json.Unmarshal([]byte(source), &root); err != nil {
					t.Fatal(err)
				}
				target := root
				if payment {
					target = root["payments"].([]any)[0].(map[string]any)
				}
				if null {
					target[field] = nil
				} else {
					delete(target, field)
				}
				body, err := json.Marshal(root)
				if err != nil {
					t.Fatal(err)
				}
				rejectBody(t, string(body), 422, "invalid_request")
			}
		}
	}
	rejectBody(t, "null", 422, "invalid_request")
	rejectBody(t, strings.Replace(source, `[{"amount":"1","payee_firm_uuid":"`+lopez+`","description":"transfer"}]`, `[null]`, 1), 422, "invalid_request")
}

