func lockDeadline(t *testing.T) {
	before := snapshot(t)
	tx, err := suite.db.Begin(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	defer func() {
		ctx, cancel := context.WithTimeout(context.Background(), time.Second)
		defer cancel()
		_ = tx.Rollback(ctx)
	}()
	if _, err := tx.Exec(t.Context(), "SELECT id FROM firms WHERE id=1 FOR UPDATE"); err != nil {
		t.Fatal(err)
	}
	start := time.Now()
	res := call(t, 0, encode(t, transfer("1")))
	expect(t, res, 504, "timeout")
	if time.Since(start) > 9*time.Second {
		t.Fatal("unbounded request")
	}
	unchanged(t, before)
	if err := tx.Rollback(t.Context()); err != nil {
		t.Fatal(err)
	}
	accepted(t, transfer("1"))
	checkState(t, []int64{4999900, 50100, 200000}, []record{{1, 2, 100, "transfer"}})
}

