func realProxy(t *testing.T, redirect bool) (string, func() int) {
	t.Helper()
	listener, err := (&net.ListenConfig{}).Listen(t.Context(), "tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatal(err)
	}
	addr := listener.Addr().String()
	if err := listener.Close(); err != nil {
		t.Fatal(err)
	}
	directory := t.TempDir()
	location := "location /internal/payments/bulk { limit_req zone=clients; proxy_pass http://" + suite.ledgers[0].addr + "; }"
	if redirect {
		location = "location /internal/payments/bulk/ { proxy_pass http://" + suite.ledgers[0].addr + "/internal/payments/bulk; }"
	}
	config := fmt.Sprintf(`daemon off;
master_process off;
pid %s/nginx.pid;
error_log %s/error.log;
events { worker_connections 64; }
http {
 access_log %s/access.log;
 client_body_temp_path %s/body;
 proxy_temp_path %s/proxy;
 limit_req_zone $binary_remote_addr zone=clients:1m rate=1r/m;
 server { listen %s; %s }
}
`, directory, directory, directory, directory, directory, addr, location)
	path := filepath.Join(directory, "nginx.conf")
	if err := os.WriteFile(path, []byte(config), 0o600); err != nil {
		t.Fatal(err)
	}
	cmd := exec.CommandContext(context.Background(), "nginx", "-p", directory, "-c", path)
	if err := cmd.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := cmd.Process.Signal(syscall.SIGQUIT); err != nil {
			t.Error(err)
		}
		if err := cmd.Wait(); err != nil {
			t.Error(err)
		}
	})
	ready := false
	for deadline := time.Now().Add(5 * time.Second); time.Now().Before(deadline); {
		connection, err := (&net.Dialer{Timeout: 100 * time.Millisecond}).DialContext(t.Context(), "tcp", addr)
		if err == nil {
			_ = connection.Close()
			ready = true
			break
		}
		time.Sleep(20 * time.Millisecond)
	}
	if !ready {
		t.Fatal("Nginx did not start")
	}
	return "http://" + addr, func() int {
		data, err := os.ReadFile(filepath.Join(directory, "access.log"))
		if err != nil {
			t.Fatal(err)
		}
		return strings.Count(string(data), `/internal/payments/bulk`)
	}
}

