func rollbackCase(t *testing.T) {
	t.Helper()
	execSQL(t, `CREATE FUNCTION reject_second() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.description='force-failure' THEN RAISE EXCEPTION 'private injected SQL details'; END IF; RETURN NEW; END $$; CREATE TRIGGER reject_second BEFORE INSERT ON payments FOR EACH ROW EXECUTE FUNCTION reject_second()`)
	t.Cleanup(func() {
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		if _, err := suite.db.Exec(ctx, "DROP TRIGGER IF EXISTS reject_second ON payments; DROP FUNCTION IF EXISTS reject_second()"); err != nil {
			t.Error(err)
		}
	})
	before := snapshot(t)
	b := transfer("1")
	b.Payments = append(b.Payments, entry{"2", nair, "force-failure"})
	res := call(t, 0, encode(t, b))
	expect(t, res, 500, "internal_error")
	for _, secret := range []string{"private injected", "reject_second", "INSERT INTO", "SQLSTATE"} {
		if strings.Contains(res.Body, secret) {
			t.Fatal("SQL detail exposed")
		}
	}
	unchanged(t, before)
}

