func fundedConcurrency(t *testing.T, n, want int) {
	t.Helper()
	execSQL(t, "UPDATE firms SET balance_cents=20 WHERE id=1")
	before := snapshot(t)
	outcomes(t, concurrent(t, n, func(int) batch { return transfer("0.01") }), want, "insufficient_funds")
	s := snapshot(t)
	if !reflect.DeepEqual(s.Balances, []int64{0, 50020, 200000}) {
		t.Fatal(s)
	}
	conserved(t, before, 20)
	checkTransfers(t, before)
}

func checkTransfers(t *testing.T, before state) {
	t.Helper()
	after := snapshot(t)
	want := append([]int64{}, before.Balances...)
	for _, p := range after.Payments {
		if p.Cents != 1 || p.Description != "transfer" {
			t.Fatal(p)
		}
		want[p.Payer-1] -= p.Cents
		want[p.Payee-1] += p.Cents
	}
	if !reflect.DeepEqual(want, after.Balances) {
		t.Fatalf("rows do not reconcile balances: %+v", after)
	}
}

func concurrent(t *testing.T, n int, makeBatch func(int) batch) []response {
	t.Helper()
	ctx, cancel := context.WithTimeout(t.Context(), 15*time.Second)
	defer cancel()
	start := make(chan struct{})
	results := make([]response, n)
	failures := make([]error, n)
	bodies := make([]string, n)
	for i := range n {
		bodies[i] = encode(t, makeBatch(i))
	}
	var wg sync.WaitGroup
	for i := range n {
		wg.Go(func() {
			<-start
			results[i], failures[i] = request(ctx, "http://"+suite.apis[i%2].addr, http.MethodPost, "/payments/bulk", "application/json", bodies[i])
		})
	}
	close(start)
	wg.Wait()
	for _, err := range failures {
		if err != nil {
			t.Fatal(err)
		}
	}
	return results
}

func conserved(t *testing.T, before state, count int) {
	t.Helper()
	after := snapshot(t)
	sum := func(a []int64) int64 {
		var n int64
		for _, v := range a {
			if v < 0 || v > maxCents {
				t.Fatal("balance outside INTEGER range")
			}
			n += v
		}
		return n
	}
	if sum(before.Balances) != sum(after.Balances) || len(after.Payments) != count {
		t.Fatalf("conservation or row count failed: %+v", after)
	}
}

