func TestFailureMappingAndReadiness(t *testing.T) {
	for _, tc := range []struct {
		err    error
		status int
		code   string
	}{{contracts.ErrInsufficientFunds, 422, "insufficient_funds"}, {contracts.ErrUnknownFirm, 422, "unknown_firm"}, {contracts.ErrBalanceOverflow, 422, "balance_overflow"}, {contracts.ErrUnavailable, 503, "unavailable"}, {context.DeadlineExceeded, 504, "timeout"}, {context.Canceled, 503, "unavailable"}, {errors.New("private SQL details"), 500, "internal_error"}} {
		p := &processor{err: tc.err}
		h := httpapi.Handler("test", "/payments/bulk", p, func(context.Context) error { return contracts.ErrUnavailable })
		w := httptest.NewRecorder()
		h.ServeHTTP(w, httptest.NewRequestWithContext(t.Context(), http.MethodPost, "/payments/bulk", strings.NewReader(valid)))
		var body contracts.ErrorResponse
		if err := json.Unmarshal(w.Body.Bytes(), &body); err != nil {
			t.Fatal(err)
		}
		if w.Code != tc.status || body.Error.Code != tc.code || strings.Contains(w.Body.String(), "private SQL") {
			t.Fatalf("wrong failure: %d %s", w.Code, w.Body.String())
		}
		for _, check := range []struct {
			method, path string
			status       int
		}{{"GET", "/healthz", 200}, {"GET", "/readyz", 503}, {"GET", "/payments/bulk", 405}, {"POST", "/unknown", 404}} {
			r := httptest.NewRecorder()
			h.ServeHTTP(r, httptest.NewRequestWithContext(t.Context(), check.method, check.path, nil))
			if r.Code != check.status {
				t.Errorf("%s: %d", check.path, r.Code)
			}
		}
	}
}

func TestRequestBoundary(t *testing.T) {
	for _, tc := range []struct {
		name, body, media string
		status, calls     int
	}{
		{"valid", valid, "application/json", 201, 1},
		{"malformed", "{", "application/json", 400, 0},
		{"unknown field", strings.Replace(valid, `"payments":`, `"extra":1,"payments":`, 1), "application/json", 400, 0},
		{"multiple documents", valid + valid, "application/json", 400, 0},
		{"number amount", strings.Replace(valid, `"1.25"`, `1.25`, 1), "application/json", 400, 0},
		{"invalid cents", strings.Replace(valid, `1.25`, `0.001`, 1), "application/json", 422, 0},
		{"missing description", strings.Replace(valid, `,"description":""`, "", 1), "application/json", 422, 0},
		{"null", "null", "application/json", 422, 0},
		{"media", valid, "text/plain", 415, 0},
		{"too large", valid + strings.Repeat(" ", int(contracts.MaxBodyBytes)), "application/json", 413, 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := &processor{}
			h := httpapi.Handler("test", "/payments/bulk", p, func(context.Context) error { return nil })
			req := httptest.NewRequestWithContext(t.Context(), http.MethodPost, "/payments/bulk", strings.NewReader(tc.body))
			req.Header.Set("Content-Type", tc.media)
			w := httptest.NewRecorder()
			h.ServeHTTP(w, req)
			if w.Code != tc.status || p.calls != tc.calls {
				t.Fatalf("status %d calls %d; want %d/%d: %s", w.Code, p.calls, tc.status, tc.calls, w.Body.String())
