		{"multiple documents", valid + valid, "application/json", 400, 0},
		{"number amount", strings.Replace(valid, `"1.25"`, `1.25`, 1), "application/json", 400, 0},
		{"invalid cents", strings.Replace(valid, `1.25`, `0.001`, 1), "application/json", 422, 0},
		{"missing description", strings.Replace(valid, `,"description":""`, "", 1), "application/json", 422, 0},
		{"null", "null", "application/json", 422, 0},
		{"media", valid, "text/plain", 415, 0},
		{"too large", valid + strings.Repeat(" ", int(contracts.MaxBodyBytes)), "application/json", 413, 0},
	} {
		t.Run(tc.name, func(t *testing.T) {
			p := &processor{}
			h := httpapi.Handler("test", "/payments/bulk", p, func(context.Context) error { return nil })
			req := httptest.NewRequestWithContext(t.Context(), http.MethodPost, "/payments/bulk", strings.NewReader(tc.body))
			req.Header.Set("Content-Type", tc.media)
			w := httptest.NewRecorder()
			h.ServeHTTP(w, req)
			if w.Code != tc.status || p.calls != tc.calls {
				t.Fatalf("status %d calls %d; want %d/%d: %s", w.Code, p.calls, tc.status, tc.calls, w.Body.String())
			}
			if tc.status == 201 && w.Body.Len() != 0 {
				t.Fatal("201 body must be empty")
			}
		})
	}
}

func TestClientPreservesOutcomesWithoutRetry(t *testing.T) {
	for _, tc := range []struct {
		status int
		body   string
		want   error
	}{{201, "", nil}, {422, `{"error":{"code":"insufficient_funds"}}`, contracts.ErrInsufficientFunds}, {503, `{"error":{"code":"unavailable"}}`, contracts.ErrUnavailable}, {500, `{"error":{"code":"internal_error"}}`, contracts.ErrInternal}, {504, `{"error":{"code":"timeout"}}`, context.DeadlineExceeded}, {502, "bad gateway", contracts.ErrUnavailable}, {500, `{"error":{"code":"insufficient_funds"}}`, contracts.ErrUnavailable}, {200, `{"error":{"code":"insufficient_funds"}}`, contracts.ErrUnavailable}} {
		var calls atomic.Int32
		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			calls.Add(1)
			if r.URL.Path != "/internal/payments/bulk" || r.Method != "POST" {
				t.Error("wrong private request")
			}
			w.WriteHeader(tc.status)
			if _, err := w.Write([]byte(tc.body)); err != nil {
				t.Error(err)
			}
		}))
		c, err := ledgerclient.New(srv.URL)
		if err != nil {
			t.Fatal(err)
		}
		err = c.Execute(t.Context(), contracts.BulkRequest{})
		srv.Close()
		if !errors.Is(err, tc.want) || calls.Load() != 1 {
			t.Errorf("status %d: %v, calls %d", tc.status, err, calls.Load())
		}
	}
}

func TestRedirectAndCancellation(t *testing.T) {
	var redirects atomic.Int32
	target := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { redirects.Add(1); w.WriteHeader(201) }))
	defer target.Close()
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, target.URL, http.StatusTemporaryRedirect)
	}))
	defer srv.Close()
	client, err := ledgerclient.New(srv.URL)
	if err != nil {
		t.Fatal(err)
	}
	if err := client.Execute(t.Context(), contracts.BulkRequest{}); !errors.Is(err, contracts.ErrUnavailable) || redirects.Load() != 0 {
		t.Fatal("payment redirect was followed", err)
	}
	release := make(chan struct{})
	slow := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		select {
		case <-r.Context().Done():
		case <-release:
		}
	}))
	defer slow.Close()
	defer close(release)
	client, err = ledgerclient.New(slow.URL)
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(t.Context(), 20*time.Millisecond)
	defer cancel()
	if err := client.Execute(ctx, contracts.BulkRequest{}); !errors.Is(err, context.DeadlineExceeded) {
		t.Fatalf("lost deadline: %v", err)
	}
	for _, url := range []string{"", "file:///tmp/x", "http://host/path", "http://user:pass@host", "http://host?x=1"} {
		if _, err := ledgerclient.New(url); err == nil {
			t.Errorf("accepted URL %q", url)
		}
	}
}

