func TestCoverageUnionUsesStatementsNotAveragedPercentages(t *testing.T) {
	root := t.TempDir()
	paths := []string{}
	for i, text := range []string{"mode: atomic\nexample/internal/a.go:1.1,2.1 9 1\nexample/internal/a.go:3.1,4.1 1 0\n", "mode: atomic\nexample/internal/a.go:1.1,2.1 9 0\nexample/internal/a.go:3.1,4.1 1 1\n", "mode: atomic\nexample/internal/a.go:1.1,2.1 9 2\nexample/internal/a.go:3.1,4.1 1 0\n"} {
		p := filepath.Join(root, string(rune('a'+i))+".out")
