			t.Fatal(err)
		}
		paths = append(paths, p)
	}
	out := filepath.Join(root, "coverage")
	if err := coverage(out, paths); err != nil {
		t.Fatal(err)
	}
	data, err := os.ReadFile(filepath.Join(out, "summary.json"))
	if err != nil {
		t.Fatal(err)
