	if !strings.Contains(string(xml), `failures="1"`) || !strings.Contains(string(xml), "original output") {
		t.Fatal("skipped case was hidden")
	}
}

func TestLiteralAssertionsBindRegistryCasesAndRealHelpers(t *testing.T) {
	root := testRoot(t)
	line, err := sourceLine(root, "tests/functional/payments_test.go", "OriginalThreePaymentSample")
	if err != nil {
		t.Fatal(err)
	}
	results := []result{{SourceURL: sourceURL(strings.Repeat("a", 40), "tests/functional/payments_test.go", line)}}
	if err := attachAssertions(root, strings.Repeat("a", 40), results); err != nil {
		t.Fatal(err)
	}
	if len(results[0].Assertions) < 2 {
		t.Fatal("delegated assertions lost their literal helpers")
	}
	foundAssert := false
	for _, snippet := range results[0].Assertions {
		data, err := os.ReadFile(filepath.Join(root, snippet.Path))
		if err != nil {
			t.Fatal(err)
		}
		want := strings.Join(strings.Split(string(data), "\n")[snippet.StartLine-1:snippet.EndLine], "\n")
		if snippet.Source != want || snippet.SHA256 == "" {
			t.Fatal("source excerpt was changed or unbound")
		}
		if len(snippet.AssertLines) > 0 {
			foundAssert = true
		}
	}
	if !foundAssert {
		t.Fatal("assertion call sites in real helpers were not located")
	}
	if err := attachAssertions(root, strings.Repeat("b", 40), results); err == nil {
		t.Fatal("foreign revision accepted")
	}
}

