func TestPublicExtensionRejectsRawConversationAndRevisionMismatch(t *testing.T) {
	root := skeleton(t)
	sha := strings.Repeat("a", 40)
	put(t, filepath.Join(root, "verification.json"), `{"SourceSHA":"`+sha+`"}`)
	for _, file := range []string{"conversation.pdf", "cases/functional-0123456789abcdef/../../raw.jsonl", "storybook/private.go"} {
		metadata, err := json.Marshal(map[string]any{"SourceSHA": sha, "CaseCount": 1, "Files": []string{file}})
		if err != nil {
			t.Fatal(err)
		}
		put(t, filepath.Join(root, "extensions.json"), string(metadata))
		if _, err := allowedPublicFiles(root); err == nil {
			t.Fatalf("unsafe extension accepted: %s", file)
		}
	}
	put(t, filepath.Join(root, "extensions.json"), `{"SourceSHA":"`+strings.Repeat("b", 40)+`","CaseCount":1,"Files":["viewer/index.html"]}`)
	if _, err := allowedPublicFiles(root); err == nil {
		t.Fatal("stale UI extension accepted")
	}
	put(t, filepath.Join(root, "extensions.json"), `{"SourceSHA":"`+sha+`","CaseCount":1,"Files":["viewer/index.html"]}`)
	files, err := allowedPublicFiles(root)
	if err != nil || !files["viewer/index.html"] {
		t.Fatalf("generated viewer was not allowed: %v", err)
	}
}

func put(t *testing.T, path, text string) {
	t.Helper()
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
