func TestBackupBuildAndTamperDetection(t *testing.T) {
	repo := t.TempDir()
	source := filepath.Join(repo, "session.jsonl")
	text := "Raw {text} % _ & $ # \\end{Verbatim} \\input{secret}\nUnicode Ω → —"
	first := sourceRecord("user", text)
	mustWrite(t, source, first)
	mustWrite(t, filepath.Join(repo, ".local", "conversation-sources"), []byte(source+"\n"))
	if err := Sync(repo); err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(repo, "docs", "conversations")
	out := filepath.Join(repo, "build")
	if err := Build(dir, out); err != nil {
		t.Fatal(err)
	}
	b, err := os.ReadFile(filepath.Join(out, "messages", "000001.txt"))
	if err != nil {
		t.Fatal(err)
	}
	if string(b) != text {
		t.Fatal("message text changed")
	}
	tex, err := os.ReadFile(filepath.Join(out, "conversation.tex"))
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(tex), "input{secret}") || !strings.Contains(string(tex), "ChatGPT-classical-dark") {
		t.Fatal("unsafe TeX or incorrect theme")
	}
	second := append(append([]byte{}, first...), sourceRecord("assistant", "unmodified response")...)
	mustWrite(t, source, second)
	if err := Sync(repo); err != nil {
		t.Fatal(err)
	}
	m, err := Verify(dir)
	if err != nil {
		t.Fatal(err)
	}
	if m.Files[0].Records != 2 {
		t.Fatal("new dialogue was not captured")
	}
	mustWrite(t, source, sourceRecord("user", "rewritten history"))
	if err := Sync(repo); err == nil {
		t.Fatal("overwrote earlier history")
	}
	mustWrite(t, filepath.Join(dir, "raw", "session.jsonl"), []byte("corrupted\n"))
	if _, err := Verify(dir); err == nil {
		t.Fatal("accepted corrupt backup")
	}
}

