		{"horizontal overflow", "Overfull \\hbox (2pt)\nOutput written on conversation.pdf", false},
		{"vertical overflow", "Overfull \\vbox (2pt)\nOutput written on conversation.pdf", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			name := filepath.Join(t.TempDir(), "compiler.log")
			mustWrite(t, name, []byte(tc.text))
			err := CheckPDFLog(name)
			if (err == nil) != tc.ok {
				t.Fatalf("expected pass=%v, error=%v", tc.ok, err)
