func TestSelectKeepsOriginalBytesAndCompleteRecords(t *testing.T) {
	line := sourceRecord("user", "amount 5800.5 — Ω \\end{document}")
	source := append([]byte("{\"type\":\"session_meta\"}\n"), line...)
	source = append(source, []byte("{\"unfinished\":")...)
	out, n, err := Select(source)
	if err != nil {
		t.Fatal(err)
	}
	if n != 1 || !bytes.Equal(out, line) {
		t.Fatalf("changed original record: %s", out)
	}
	if _, _, err := Select([]byte("broken\n")); err == nil {
		t.Fatal("accepted corrupted complete record")
	}
}

